#!/usr/bin/env python3
"""Generate explicitly synthetic logs and a comparison; execute no candidate."""
import argparse
import json
from pathlib import Path

parser = argparse.ArgumentParser()
parser.add_argument("--output-dir", required=True)
args = parser.parse_args()
out = Path(args.output_dir)
out.mkdir(parents=True, exist_ok=True)
values = {"A": 10.0, "B": 10.1}
for name, value in values.items():
    text = (
        "SYNTHETIC TRUE: generated by examples/minimal/generate_synthetic.py; not an author run.\n"
        "COMMAND: python3 generate_synthetic.py (fixture generator, not a candidate executor)\n"
        f"CANDIDATE: {name} (organization-synthetic fixture)\n"
        f"VALUE: {value:.1f}\n"
        "STATUS: synthetic-success; no scientific method was executed\n"
        "EXIT_CODE: 0 (generator fixture record)\n"
    )
    (out / f"candidate_{name.lower()}.log").write_text(text, encoding="utf-8")
comparison = {
    "comparison": {
        "candidate_a": values["A"],
        "candidate_b": values["B"],
        "absolute_difference": round(abs(values["A"] - values["B"]), 6),
        "absolute_tolerance": 0.25,
        "tolerance_registered_before_fixture_generation": True,
        "difference_attribution": "Fixed offset configured in the synthetic fixture generator; not a real algorithm comparison."
    }
}
(out / "comparison.json").write_text(json.dumps(comparison, indent=2) + "\n", encoding="utf-8")
print("synthetic fixtures generated; no candidate command was executed")
